interface Greeting { default String word() { return "Hello"; } }
class StudentGreeting implements Greeting { }

class Main {
    public static void main(String[] args) {
        Greeting g = new StudentGreeting();
        System.out.println(g.word());
    }
}

interface A { default String combine() { return "A"; } }
interface B { default String combine() { return "B"; } }
class Both implements A, B {
    @Override
    public String combine() { return B.super.combine() + A.super.combine(); }
}

class Main {
    public static void main(String[] args) {
        System.out.println(new Both().combine());
    }
}

interface Label { default String label() { return "interface"; } }
class Parent { public String label() { return "class"; } }
class Child extends Parent implements Label { }

class Main {
    public static void main(String[] args) {
        System.out.println(new Child().label());
    }
}
